let renderer,game,inLobby=true,options={mode:'ai',theme:0,turnTime:40,difficulty:'normal'},held=new Set(),modal=null,wasPaused=false,installEvent=null,last=performance.now(),accumulator=0,uiTime=0,saveTime=0,bannerTime=0,toastTime=0,record={played:0,wins:0},lastSave=null;
