function frame(now){let dt=Math.min((now-last)/1000,.1);last=now;audio.setDanger(!inLobby&&!!game?.sudden&&game.phase!=='ended');tickVictory(dt);tickCharge(dt);if(!inLobby&&!game.paused){accumulator=Math.min(accumulator+dt,.2);while(accumulator>=STEP){let left=held.has('left'),right=held.has('right');game.input=left===right?0:left?-1:1;game.step(STEP);accumulator-=STEP;handleEvents();if(game.paused)break}saveTime+=dt;if(saveTime>=2){saveTime=0;saveBattle()}}else accumulator=0;renderer.render(dt);uiTime+=dt;if(uiTime>=.1){uiTime=0;sync()}bannerTime-=dt;if(bannerTime<=0)$('turnBanner').classList.remove('show');toastTime-=dt;if(toastTime<=0)$('toast').classList.remove('show');requestAnimationFrame(frame)}
const charge=new Critters.PowerCharge();let angleHeld=0,angleRepeat=0;
function cancelCharge(){charge.cancel();angleHeld=0;if(game){game.charging=false;game.ropeAdjust=0;}}
function shotButton(){audio.init();if(inLobby||!game.canFire())return;if(game.weapon===Critters.ROPE){game.fire();handleEvents();sync();return;}const utility=['heal','shield','quake','blink'].includes(WEAPONS[game.weapon].id);if(utility){game.fire();handleEvents();sync();return;}if(!charge.active){held.clear();game.input=0;charge.start();game.charging=true;game.power=1;audio.charge();$('arsenal').hidden=true;}else{game.power=charge.value;charge.active=false;game.charging=false;game.fire(game.angle,game.power);handleEvents();}sync();}
function updateChargeUI(){if(inLobby||!game)return;const g=game,utility=['heal','shield','quake','blink'].includes(WEAPONS[g.weapon].id);$('angleValue').textContent=Math.round(g.elevation??45)+'°';$('worldAngle').textContent='실제 '+Math.round(g.angle)+'°';$('powerValue').textContent=Math.round(charge.active?charge.value:g.power)+'%';const value=charge.active?charge.value:g.power;$('chargeMeter').setAttribute('aria-valuenow',Math.round(value));$('chargeFill').style.width=value+'%';$('chargeNeedle').style.left=value+'%';$('chargeMeter').classList.toggle('charging',charge.active);$('chargeHint').textContent=charge.active?'지금 누르면 발사':utility?'즉시 사용 도구':'발사 → 시작 → 다시 눌러 발사';$('fire').firstChild.textContent=utility?'사용 ':charge.active?'발사! ':'파워 ';$('fire').classList.toggle('charging',charge.active);for(const id of ['angleUp','angleDown','faceFlip'])$(id).disabled=!g.canFire()||charge.active;$('loadout').disabled=!g.canFire()||charge.active;if(g.weapon===Critters.ROPE){$('fire').firstChild.textContent=g.rope?'놓기 ':g.hook?'취소 ':'걸기 ';$('chargeHint').textContent=g.rope?'자동 당기기 · 감기/늘리기 · 다시 누르면 놓기':'구조물을 터치해 걸기 · 또는 고도 조절 후 발사';}for(const id of ['angleUp','angleDown','faceFlip'])$(id).disabled=!g.canFire()||charge.active||!!g.rope;$('ropeTools').hidden=!g.rope;$('ropeLength').textContent=g.rope?'로프 '+Math.round(g.rope.length):'';}
function tickCharge(dt){if(!game||inLobby)return;if(charge.active&&(game.paused||game.phase!=='aim'||!game.human()||game.active.hp<=0))cancelCharge();if(charge.active){game.power=charge.step(dt);updateChargeUI();}if(angleHeld&&game.canFire()&&!charge.active){angleRepeat-=dt;if(angleRepeat<=0){game.setElevation((game.elevation??45)+angleHeld*2);angleRepeat=.09;updateChargeUI();}}if(!game.paused&&(game.walkDistance||0)>=12){game.walkDistance=0;audio.walk();}}
try{renderer=new CritterRenderer($('scene'));setupLobby();$('boot').style.opacity=0;setTimeout(()=>$('boot').hidden=true,500);requestAnimationFrame(frame)}catch(e){$('boot').hidden=true;$('fatal').hidden=false;console.error(e);return}

const PROGRESS='pocket-critters-campaign-v1';
let progress=read(PROGRESS,{cleared:[],stars:{}}),stageResult='';
progress.cleared=Array.isArray(progress.cleared)?progress.cleared.filter(n=>Number.isInteger(n)&&n>=0&&n<Critters.STAGES.length):[];progress.stars=progress.stars||{};
