function launchStage(id){if(id>0&&!progress.cleared.includes(id-1))return;options={...options,stage:id,layout:id,theme:id};startGame();}
function campaignMenu(){const cleared=progress.cleared;$('campaignProgress').textContent=cleared.length+'/'+Critters.STAGES.length+' 클리어 · '+Critters.unlockedFor(cleared).length+'/'+WEAPONS.length+' 무기·도구';const buttons=Critters.STAGES.map(s=>{const locked=s.id>0&&!cleared.includes(s.id-1),b=document.createElement('button');b.className='stage-card'+(locked?' locked':'')+(s.boss?' boss-stage':'');b.dataset.stage=s.id;b.disabled=locked;const canvas=document.createElement('canvas');canvas.width=280;canvas.height=100;const ctx=canvas.getContext('2d'),preview=new Game({theme:s.theme,layout:s.layout,seed:s.seed}),theme=THEMES[s.theme],gr=ctx.createLinearGradient(0,0,0,100);gr.addColorStop(0,theme.sky[0]);gr.addColorStop(1,theme.sky[1]);ctx.fillStyle=gr;ctx.fillRect(0,0,280,100);ctx.fillStyle=theme.earth;ctx.beginPath();ctx.moveTo(0,100);for(let x=0;x<1600;x+=8)ctx.lineTo(x/1600*280,preview.heights[x]/900*100);ctx.lineTo(280,100);ctx.fill();ctx.fillStyle=theme.sea;ctx.fillRect(0,88,280,12);b.append(canvas);for(const [tag,text] of [['b',String(s.id+1).padStart(2,'0')+' · '+s.name+(s.boss?' 👑 BOSS':'')],['small',locked?'이전 스테이지를 먼저 클리어하세요':s.tip],['em','보상 · '+(s.boss?s.rewardText+(Number.isInteger(s.unlock)?' · '+WEAPONS[s.unlock].name+' 해금':''):Number.isInteger(s.unlock)?WEAPONS[s.unlock].name:s.rewardText)],['small',s.field?.label||''],['small','★'.repeat(progress.stars[s.id]||0)+'☆'.repeat(3-(progress.stars[s.id]||0))]]){const el=document.createElement(tag);el.textContent=text;b.append(el);}b.onclick=()=>launchStage(s.id);return b;});$('stageGrid').replaceChildren(...buttons);showModal('campaignPanel');}
$('shopEntry').onclick=()=>PCMeta.open('heroes');$('partyEntry').onclick=()=>PCMeta.open('heroes');$('missionEntry').onclick=()=>PCMeta.open('missions');$('metaBattleEntry').onclick=()=>PCMeta.open('missions');
for(const report of read('pc-pending-rewards',[]))PCWallet.run('completeBattle',report).then(()=>store('pc-pending-rewards',read('pc-pending-rewards',[]).filter(r=>r.id!==report.id))).catch(e=>console.warn(e.message));
PCWallet.run('migrate',progress.cleared).catch(e=>console.warn(e.message));
$('campaignOpen').onclick=campaignMenu;$('campaignClose').onclick=hideModal;
const mapSelect=document.createElement('select');mapSelect.ariaLabel='자유 대전 지도';for(const s of Critters.STAGES){const o=document.createElement('option');o.value=s.id;o.textContent=String(s.id+1).padStart(2,'0')+' · '+s.name;mapSelect.append(o);}mapSelect.value=options.theme;mapSelect.onchange=()=>{delete options.stage;options.layout=+mapSelect.value;options.theme=+mapSelect.value;applyTheme();game=new Game({...options,seed:THEMES[options.theme].seed});game.drain();renderer.setGame(game,true);};$('maps').replaceChildren(mapSelect);

$('start').onclick=()=>{delete options.stage;options.layout=options.theme;startGame()};$('resume').onclick=()=>{try{let data=read(SAVE,null),g=Game.restore(data);if(!g)throw Error('invalid save');startGame(g)}catch{try{localStorage.removeItem(SAVE)}catch{}$('resume').hidden=true;alert('저장된 전투를 읽을 수 없어 새 전투로 시작합니다.');startGame()}};
document.querySelectorAll('[data-value]').forEach(b=>b.onclick=()=>{options.mode=b.dataset.value;applyTheme()});document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{options.theme=+b.dataset.theme;applyTheme();game=new Game({...options,seed:THEMES[options.theme].seed});game.drain();renderer.setGame(game,true)});$('difficulty').onchange=()=>{options.difficulty=$('difficulty').value;applyTheme()};$('turnTime').onchange=()=>{options.turnTime=+$('turnTime').value;applyTheme()};
$('angle').oninput=$('power').oninput=()=>{game.setAim(+$('angle').value,+$('power').value);$('angleValue').textContent=Math.round(game.angle)+'°';$('powerValue').textContent=Math.round(game.power)+'%'};$('fire').onclick=shotButton;for(const [id,direction] of [['angleUp',1],['angleDown',-1]]){$(id).onpointerdown=e=>{if(!game.canFire()||charge.active)return;e.preventDefault();$(id).setPointerCapture(e.pointerId);angleHeld=direction;angleRepeat=.28;game.setElevation((game.elevation??45)+direction*2);updateChargeUI();};for(const ev of ['pointerup','pointercancel','lostpointercapture'])$(id).addEventListener(ev,()=>angleHeld=0);$(id).onclick=e=>{if(e.detail===0){game.setElevation((game.elevation??45)+direction*2);updateChargeUI();}};}
for(const [id,dir]of [['ropeShort',-1],['ropeLong',1]]){$(id).onpointerdown=e=>{if(!game.rope||game.paused)return;e.preventDefault();$(id).setPointerCapture(e.pointerId);game.ropeAdjust=dir;};for(const ev of ['pointerup','pointercancel','lostpointercapture'])$(id).addEventListener(ev,()=>game.ropeAdjust=0);}$('ropeRelease').onclick=()=>{game.releaseRope();handleEvents();sync();};
$('faceFlip').onclick=()=>{game.turnFacing(-game.active.face);sync();};
$('musicVolume').value=audio.musicVolume*100;$('sfxVolume').value=audio.sfxVolume*100;for(const [id,key]of [['musicVolume','musicVolume'],['sfxVolume','sfxVolume']])$(id).oninput=()=>{audio.init();audio[key]=+$(id).value/100;audio.apply();audio.save();};$('audio').style.opacity=audio.enabled?'1':'.5';$('audio').title=$('audio').ariaLabel=audio.enabled?'소리 끄기':'소리 켜기';
$('jump').onclick=()=>{game.jump();handleEvents();sync()};for(let id of ['left','right']){$(id).onpointerdown=e=>{if(!game.canMove())return;e.preventDefault();held.add(id);$(id).setPointerCapture(e.pointerId)};for(let ev of ['pointerup','pointercancel','lostpointercapture'])$(id).addEventListener(ev,()=>held.delete(id))}
$('loadout').onclick=weaponMenu;$('closeArsenal').onclick=()=>$('arsenal').hidden=true;$('pause').onclick=()=>showModal('pauseMenu');$('continue').onclick=hideModal;$('restart').onclick=()=>startGame();$('toLobby').onclick=()=>{if(!inLobby)saveBattle();hideModal();setupLobby()};$('rematch').onclick=()=>startGame();$('resultLobby').onclick=()=>{hideModal();setupLobby()};$('help').onclick=()=>showModal('guide');$('closeGuide').onclick=hideModal;$('brand').onclick=e=>{e.preventDefault();if(inLobby)return;showModal('pauseMenu')};$('overview').onclick=()=>{renderer.overview=!renderer.overview;renderer.manual=0;$('overview').textContent=renderer.overview?'병사로 돌아가기 ⌖':'전장 보기 ⌖'};$('audio').onclick=()=>{audio.init();audio.enabled=!audio.enabled;$('audio').style.opacity=audio.enabled?'1':'.5';$('audio').title=$('audio').ariaLabel=audio.enabled?'소리 끄기':'소리 켜기';audio.tone(550)};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();if(screen.orientation?.lock)try{await screen.orientation.lock('landscape')}catch{}}catch{if(!inLobby)toast('이 기기에서는 브라우저 메뉴에서 전체 화면을 사용해 주세요.')}};
window.addEventListener('resize',()=>renderer.resize());document.addEventListener('visibilitychange',()=>{held.clear();if(document.hidden&&!inLobby&&!modal&&game.phase!=='ended')showModal('pauseMenu');last=performance.now();accumulator=0});window.addEventListener('blur',()=>{held.clear();if(!inLobby&&!modal&&game.phase!=='ended')showModal('pauseMenu')});window.addEventListener('pagehide',saveBattle);
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Escape'){if(modal==='pauseMenu')hideModal();else if(!inLobby&&!modal)showModal('pauseMenu');return}if(inLobby||modal)return;let k=e.key.toLowerCase();if(['a','d','w','arrowleft','arrowright','arrowup',' '].includes(k))e.preventDefault();if(k==='a'||k==='arrowleft')held.add('left');if(k==='d'||k==='arrowright')held.add('right');if((k==='w'||k==='arrowup')&&!e.repeat)game.jump();if(k===' '&&!e.repeat)shotButton();if(['1','2','3','4'].includes(k)){game.select(+k-1);sync()}});document.addEventListener('keyup',e=>{if(['a','arrowleft'].includes(e.key.toLowerCase()))held.delete('left');if(['d','arrowright'].includes(e.key.toLowerCase()))held.delete('right')});
let drag=null;$('scene').onpointerdown=e=>{if(inLobby||modal)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};$('scene').setPointerCapture(e.pointerId)};$('scene').onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>5)drag.moved=true;if(drag.moved)renderer.pan(dx,dy);drag.x=e.clientX;drag.y=e.clientY};$('scene').onpointerup=e=>{if(!drag)return;if(!drag.moved){let p=renderer.worldPoint(e.clientX,e.clientY);if(game.canFire()&&game.weapon===Critters.ROPE){if(game.aimRopeAt(p.x,p.y)){if(game.rope)game.releaseRope();game.fire();}handleEvents();sync();drag=null;return;}if(game.canFire()&&WEAPONS[game.weapon].kind==='blink'){game.setTeleportTarget(p.x,p.y);handleEvents();sync();drag=null;return;}let u=game.alive().find(u=>Math.hypot(u.x-p.x,u.y-p.y)<55);if(u){renderer.focus(u);renderer.manual=4}}drag=null};$('scene').onpointercancel=()=>drag=null;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e});$('install').onclick=async()=>{if(installEvent){await installEvent.prompt();await installEvent.userChoice;installEvent=null}else showModal('installGuide')};$('closeInstall').onclick=hideModal;

window.addEventListener('pc:external-pause',()=>{if(!inLobby&&!modal&&game.phase!=='ended')showModal('pauseMenu')});window.addEventListener('pc:cloud-loaded',()=>{if(!inLobby){hideModal();setupLobby()}else $('resume').hidden=false});window.addEventListener('error',e=>{if(!inLobby){game.paused=true;toast('오류로 일시정지했습니다. 새로고침하면 저장된 턴을 이어갈 수 있습니다.',15)}console.error(e.error)});
